import 'package:flutter/material.dart';import 'api.dart';
class UserManagementScreen extends StatefulWidget{const UserManagementScreen({super.key});@override State<UserManagementScreen> createState()=>_State();}
class _State extends State<UserManagementScreen>{List requests=[],users=[];bool loading=true;Future<void> load()async{try{final a=await adminApi.membership(),b=await adminApi.users();if(mounted)setState((){requests=a;users=b;loading=false;});}catch(_){if(mounted)setState(()=>loading=false);}}@override void initState(){super.initState();load();}Future<void> decide(String id,String status)async{await adminApi.membershipDecision(id,status);load();}Future<void> role(String id,String value)async{await adminApi.changeRole(id,value);load();}@override Widget build(BuildContext c){if(loading)return const Center(child:CircularProgressIndicator());return DefaultTabController(length:2,child:Scaffold(appBar:const TabBar(tabs:[Tab(text:'Applications'),Tab(text:'Users')]),body:TabBarView(children:[ListView(children:requests.map((r)=>Card(child:ListTile(title:Text(r['applicant_name']??''),subtitle:Text(r['applicant_email']??''),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>decide(r['id'],'APPROVED'),icon:const Icon(Icons.check,color:Colors.green)),IconButton(onPressed:()=>decide(r['id'],'REJECTED'),icon:const Icon(Icons.close,color:Colors.red))])))).toList()),ListView(children:users.map((u)=>ListTile(title:Text(u['username']??''),subtitle:Text('Verified: '+(u['is_verified_student']??false).toString()),trailing:DropdownButton<String>(value:u['role'],items:const['MEMBER','ADMIN'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>v==null?null:role(u['id'],v)))).toList())])));}}
